// Turns raw Gmail messages into short, clean emails (fewer tokens for the agent).
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  if (!m.id) continue;
  let body = m.text || m.snippet || '';
  body = body.replace(/\r/g, '');
  body = body.split(/\n-- ?\n/)[0];                 // drop the signature
  body = body.split(/\nOn .{0,200}wrote:\n/)[0];     // drop quoted replies (English)
  body = body.split(/\nEl .{0,200}escribió:\n/)[0];  // drop quoted replies (Spanish)
  body = body.replace(/\n{3,}/g, '\n\n').trim();
  if (body.length > 1500) body = body.slice(0, 1500) + ' [truncated]';
  out.push({ json: {
    id: m.id,
    from: (m.from && m.from.text) || m.From || '',
    subject: m.subject || m.Subject || '(no subject)',
    date: m.date || '',
    body
  } });
}
// always return at least one item, so the calling workflow keeps running
return out.length ? out : [{ json: { _empty: true } }];
